const ENCODING_TYPES = ['br', 'gzip', 'deflate'] as const
type Encoding = (typeof ENCODING_TYPES)[number]
const cacheControlNoTransformRegExp = /(?:^|,)\s*?no-transform\s*?(?:,|$)/i

type ContentTypeFilter = RegExp | ((contentType: string) => boolean)

interface CompressionOptions {
  encoding?: Encoding
  threshold?: number
  contentTypeFilter?: ContentTypeFilter
}

const isEncodingSupported = (encoding: Encoding): boolean => {
  try {
    new CompressionStream(encoding as CompressionFormat)
    return true
  } catch {
    return false
  }
}

