    it('should prefer gzip over deflate when q values are equal', async () => {
      const app = buildAppDefault()
      const res = await app.request('/large', {
        headers: { 'Accept-Encoding': 'gzip;q=0.5, deflate;q=0.5' },
      })
      expect(res.headers.get('Content-Encoding')).toBe('gzip')
    })
  })

  // Node 20 does not natively support `CompressionStream('br')`, so the next two
  // describe blocks stub the global to (a) advertise Brotli support and (b)
  // advertise no Brotli support so we can exercise both branches.
  describe('Brotli (supported)', () => {
    const OriginalCompressionStream = globalThis.CompressionStream

    beforeAll(() => {
      vi.stubGlobal(
        'CompressionStream',
        class CompressionStreamStub {
          constructor(format: string) {
            if (format === 'br') {
              // Passthrough — verifies selection wiring without requiring a real
              // brotli encoder in the test runtime.
              return new TransformStream()
            }
            return new OriginalCompressionStream(format as CompressionFormat)
          }
        }
      )
    })

    afterAll(() => {
      vi.unstubAllGlobals()
    })

    const buildApp = () => {
      const app = new Hono()
      app.use('*', compress())
      app.get('/large', (c) => {
        c.header('Content-Type', 'text/plain')
        c.header('Content-Length', '1024')
        return c.text('a'.repeat(1024))
      })
      app.get('/strong-etag', (c) => {
        c.header('Content-Type', 'text/plain')
        c.header('Content-Length', '1024')
        c.header('ETag', '"strong-etag"')
        return c.text('a'.repeat(1024))
      })
      app.get('/small', (c) => {
        c.header('Content-Type', 'text/plain')
        c.header('Content-Length', '5')
        return c.text('small')
      })
      app.get('/jpeg-image', (c) => {
        c.header('Content-Type', 'image/jpeg')
        c.header('Content-Length', '1024')
        return c.body(new Uint8Array(1024))
      })
      return app
    }

    it('should select brotli when Accept-Encoding is br', async () => {
      const app = buildApp()
      const res = await app.request('/large', {
        headers: { 'Accept-Encoding': 'br' },
      })
      expect(res.headers.get('Content-Encoding')).toBe('br')
      expect(res.headers.get('Content-Length')).toBeNull()
    })

    it('should prefer brotli over gzip and deflate when all are accepted', async () => {
      const app = buildApp()
      const res = await app.request('/large', {
        headers: { 'Accept-Encoding': 'gzip, deflate, br' },
      })
      expect(res.headers.get('Content-Encoding')).toBe('br')
    })

    it('should prefer brotli over gzip when q values are equal', async () => {
      const app = buildApp()
      const res = await app.request('/large', {
        headers: { 'Accept-Encoding': 'gzip;q=0.9, br;q=0.9' },
      })
      expect(res.headers.get('Content-Encoding')).toBe('br')
    })

    it('should fall back to gzip when brotli is rejected with q=0', async () => {
      const app = buildApp()
      const res = await app.request('/large', {
        headers: { 'Accept-Encoding': 'br;q=0, gzip' },
      })
      expect(res.headers.get('Content-Encoding')).toBe('gzip')
    })

    it('should honor the encoding: "br" option', async () => {
      const app = new Hono()
      app.use('*', compress({ encoding: 'br' }))
      app.get('/large', (c) => {
        c.header('Content-Type', 'text/plain')
        c.header('Content-Length', '1024')
        return c.text('a'.repeat(1024))
      })
      const res = await app.request('/large', {
        headers: { 'Accept-Encoding': 'br, gzip' },
      })
      expect(res.headers.get('Content-Encoding')).toBe('br')
    })

    it('should not compress with brotli when the encoding option is gzip', async () => {
      const app = new Hono()
      app.use('*', compress({ encoding: 'gzip' }))
      app.get('/large', (c) => {
        c.header('Content-Type', 'text/plain')
        c.header('Content-Length', '1024')
        return c.text('a'.repeat(1024))
      })
      const res = await app.request('/large', {
        headers: { 'Accept-Encoding': 'br' },
      })
      expect(res.headers.get('Content-Encoding')).toBeNull()
    })

    it('should respect threshold with brotli', async () => {
      const app = buildApp()
      const res = await app.request('/small', {
        headers: { 'Accept-Encoding': 'br' },
      })
      expect(res.headers.get('Content-Encoding')).toBeNull()
      expect(res.headers.get('Content-Length')).toBe('5')
    })

    it('should respect contentTypeFilter with brotli', async () => {
      const app = new Hono()
      app.use('*', compress({ contentTypeFilter: /^application\/json/, threshold: 0 }))
      app.get('/text', (c) => c.text('a'.repeat(1024)))
      app.get('/json', (c) => c.json({ data: 'a'.repeat(1024) }))
      const text = await app.request('/text', {
        headers: { 'Accept-Encoding': 'br' },
      })
      expect(text.headers.get('Content-Encoding')).toBeNull()
      const json = await app.request('/json', {
        headers: { 'Accept-Encoding': 'br' },
      })
      expect(json.headers.get('Content-Encoding')).toBe('br')
    })

    it('should skip non-compressible content types under brotli', async () => {
      const app = buildApp()
      const res = await app.request('/jpeg-image', {
        headers: { 'Accept-Encoding': 'br' },
      })
      expect(res.headers.get('Content-Encoding')).toBeNull()
      expect(res.headers.get('Content-Type')).toBe('image/jpeg')
    })

    it('should convert strong ETag to weak ETag when compressing with brotli', async () => {
      const app = buildApp()
      const res = await app.request('/strong-etag', {
        headers: { 'Accept-Encoding': 'br' },
      })
      expect(res.headers.get('Content-Encoding')).toBe('br')
      expect(res.headers.get('ETag')).toBe('W/"strong-etag"')
    })
  })

  describe('Brotli (unsupported runtime)', () => {
    const OriginalCompressionStream = globalThis.CompressionStream

    beforeAll(() => {
      vi.stubGlobal(
        'CompressionStream',
        class CompressionStreamStub {
          constructor(format: string) {
            if (format === 'br') {
              throw new TypeError('Brotli not supported in this runtime')
            }
            return new OriginalCompressionStream(format as CompressionFormat)
          }
        }
      )
    })

    afterAll(() => {
      vi.unstubAllGlobals()
    })

    it('should fall back to gzip when br is unsupported but accepted alongside gzip', async () => {
      const app = new Hono()
      app.use('*', compress())
      app.get('/large', (c) => {
        c.header('Content-Type', 'text/plain')
        c.header('Content-Length', '1024')
        return c.text('a'.repeat(1024))
      })
      const res = await app.request('/large', {
        headers: { 'Accept-Encoding': 'br, gzip' },
      })
      expect(res.headers.get('Content-Encoding')).toBe('gzip')
    })

    it('should not compress when only br is accepted and the runtime cannot encode it', async () => {
      const app = new Hono()
      app.use('*', compress())
      app.get('/large', (c) => {
        c.header('Content-Type', 'text/plain')
        c.header('Content-Length', '1024')
        return c.text('a'.repeat(1024))
      })
      const res = await app.request('/large', {
        headers: { 'Accept-Encoding': 'br' },
      })
      expect(res.headers.get('Content-Encoding')).toBeNull()
    })

    it('should not compress when encoding: "br" is configured but unsupported', async () => {
      const app = new Hono()
      app.use('*', compress({ encoding: 'br' }))
      app.get('/large', (c) => {
        c.header('Content-Type', 'text/plain')
        c.header('Content-Length', '1024')
        return c.text('a'.repeat(1024))
      })
      const res = await app.request('/large', {
        headers: { 'Accept-Encoding': 'br, gzip' },
      })
      expect(res.headers.get('Content-Encoding')).toBeNull()
    })
  })
})

